def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    opp_urgencies = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
            urg = 0.0
            if opp.get('no_water_days', 0) >= 2:
                urg += 2.0
            elif opp.get('no_water_days', 0) == 1:
                urg += 1.0
            if opp.get('hp', 10) <= 2:
                urg += 2.0
            elif opp.get('hp', 10) <= 4:
                urg += 1.0
            opp_urgencies.append(urg)

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_urg = max(opp_urgencies) if opp_urgencies else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    my_risk = 0.0
    if no_water >= 2:
        my_risk += 2.5
    elif no_water == 1:
        my_risk += 1.2
    if hp <= 2:
        my_risk += 2.5
    elif hp <= 4:
        my_risk += 1.2

    base = 16.0 + 18.0 * scarcity

    if my_risk >= 4.0:
        target = max(base + 30.0, highest_prev + 8.0, 62.0)
    elif my_risk >= 2.0:
        target = max(base + 16.0, avg_prev + 4.0, 42.0)
    else:
        if supply >= 22 and max_urg < 2.0:
            target = min(base, max(10.0, avg_prev * 0.55))
        elif supply >= 19:
            target = max(base, avg_prev * 0.72)
        else:
            target = max(base + 8.0, avg_prev * 0.88)
            if max_urg >= 2.0:
                target = max(target, highest_prev + 2.0)

    if day >= 8 and hp > 4 and no_water == 0:
        target *= 0.92

    reserve = 0.0
    if day <= 7:
        reserve = 25.0
    elif day <= 9:
        reserve = 10.0

    spend_cap = max(0.0, budget - reserve)
    if my_risk >= 2.0:
        spend_cap = budget

    bid = min(target, spend_cap if spend_cap > 0 else budget)

    if my_risk == 0.0 and highest_prev >= 120.0 and supply >= 20:
        bid = min(bid, 22.0)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

